from openpyxl.styles.fills import PatternFill
wb=openpyxl.load_workbook('/root/data/workbook.xlsx')
ws=wb['Task']

def fill_sig(cell):
    f=cell.fill
    if f is None:
        return None
    fg=getattr(f,'fgColor',None)
    bg=getattr(f,'bgColor',None)
    def color_str(c):
        if c is None:
            return None
        return f"{c.type}:{getattr(c,'rgb',None)}:{getattr(c,'indexed',None)}:{getattr(c,'theme',None)}:{getattr(c,'tint',None)}"
    return f"pattern={f.patternType},fg={color_str(fg)},bg={color_str(bg)}"

